1	/**
2	 * Record the two build lanes of the `angular-super-productivity-v2-13-15`
3	 * migration cell — the Angular 8 pre-Ivy ViewEngine cell, and the fourth
4	 * independent application driven over the Angular adapter spine.
5	 *
6	 * Lane one is the era baseline: the pinned tree on its own cell — Node 12.14.1
7	 * under Rosetta 2, yarn 1.21.1, the era closure restored frozen from the
8	 * committed 2019 `yarn.lock` — built twice with the repository's own
9	 * `ng build --aot --prod` and compared file for file. The ingest recorded a
10	 * green first build; what this lane measures is whether that build is *the same
11	 * build twice*, which is a different question and gets a different answer.
12	 *
13	 * Lane two is the migrated tree: the adapter's composed changeset for the
14	 * Angular 16.2 cell, computed over the same pinned tree. Nothing in this driver
15	 * decides what to change. Every such decision lives in `@versionless/angular`,
16	 * which knows nothing about this application.
17	 *
18	 * This driver is fixture-scoped: it knows where this fixture's lanes were
19	 * materialised, and nothing else.
20	 */
21	
22	import { readdir, readFile, mkdir, writeFile } from 'node:fs/promises';
23	import * as path from 'pathe';
24	import {
25		migrateAngularCliEraWorkspace,
26		ANGULAR_16_BROWSER_CELL,
27		type AngularMigration,
28		type WorkspaceFile,
29	} from '../../../frameworks/angular/src/index.ts';
30	import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
31	import {
32		inventoryOf,
33		isByteStable,
34		sealRecord,
35		verifySealedRecord,
36		type DistEntry,
37		type SealedRecord,
38	} from './angular-factoriolab-build-lanes-run.ts';
39	
40	const repositoryRoot = path.resolve(import.meta.dirname, '../../../..');
41	
42	export const EVIDENCE_DIRECTORY = path.join(
43		repositoryRoot,
44		'evidence/runs/angular-super-productivity-v2-13-15',
45	);
46	
47	export const UNIT = 'lrapr-t006/u18-super-productivity-migration-lanes';
48	export const CONSENT = 'VL-LEGACY-CORPUS-2026-08-10';
49	
50	export const SOURCE_TREE = path.join(
51		repositoryRoot,
52		'.versionless/cache/angular-super-productivity-v2-13-15-source/verify/extracted',
53		'super-productivity-2943c5c4f13c3ce4dece0abf4f9c39739dde4192',
54	);
55	export const BASELINE_DIRECTORY = path.join(
56		repositoryRoot,
57		'.versionless/cache/angular-super-productivity-v2-13-15-baseline',
58	);
59	
60	export const ERA_LANE_FILE = 'u18-era-baseline.json';
61	export const CHANGESET_FILE = 'u18-composed-changeset.json';
62	
63	/**
64	 * What the ingest's single green build did and did not settle, restated here so
65	 * a reader does not have to go and find it.
66	 */
67	export const ERA_VARIANT =
68		"The repository's own `buildFrontend` command — `node --max_old_space_size=4096 ./node_modules/@angular/cli/bin/ng build --aot --prod` — with its `yarn preCheck` (lint plus unit tests) prefix omitted, so that this measures a build and not a test run. The Electron sidecar that the manifest names as its `main` entry point is out of build scope and was never invoked on either lane. The production configuration this command selects turns on `serviceWorker`, so ngsw-worker.js, safety-worker.js and a generated ngsw.json are part of the emitted inventory, and `webWorkerTsConfig` compiles the two application web workers (lz, reminder) as separate chunks.";
69	
70	export const ERA_NOT_ESTABLISHED: readonly string[] = Object.freeze([
71		'Two consecutive builds on one host measure repeatability, not reproducibility. Nothing here establishes what another host, another day or another clock would emit — and on this fixture the same host on the same day already disagreed with itself.',
72		'No browser opened these bundles. Nothing about their behaviour, boot or runtime correctness is observed.',
73		'The ingest recorded this application as installing frozen and building green on the first attempt with zero deviations. That remains true and is not contradicted here: a green build and a byte-stable build are different claims, and only the first one was ever made.',
74		'The Electron sidecar was not built, not run and not analysed. Its dependencies are declared in the same manifest and are carried into no claim here.',
75	]);
76	
77	export const RECORDED_RISKS: readonly string[] = Object.freeze([
78		'The emitted service worker prefetches https://fonts.googleapis.com/** and https://fonts.gstatic.com/** at runtime, as ngsw-config.json declares. No lane here made that request, so nothing is established about what happens when it fails or is blocked.',
79		'node-sass ^4.12.0 declares a postinstall that fetches or compiles a native binding. Both the ingest install and this lane ran with lifecycle scripts disabled; every .scss input still compiled and styles.css still emitted, so nothing in the build path required that binding. That is a reading of this build, not a general claim about node-sass.',
80		'The manifest declares one git-protocol dependency, jira2md, with no version and no registry integrity hash. The era lane consumed it exactly as the committed lockfile resolved it; the migrated cell records a disposition for it rather than carrying an unpinned git specifier forward.',
81	]);
82	
83	export type LaneInput = Readonly<{
84		first: readonly DistEntry[];
85		second: readonly DistEntry[];
86		firstSeconds: number;
87		nodeVersion: string;
88		/**
89		 * Paths whose digests differ between the two rebuilds, and what was found
90		 * when each was chased. An empty list on a byte-stable lane is the only
91		 * honest empty list here.
92		 */
93		instability: readonly InstabilityFinding[];
94	}>;
95	
96	/** One file that two consecutive builds of the same tree did not agree on. */
97	export type InstabilityFinding = Readonly<{
98		path: string;
99		observed: string;
100		cause: string;
101		consequential: boolean;
102	}>;
103	
104	/** Paths present in both inventories whose digests differ. */
105	export function differingPaths(
106		first: readonly DistEntry[],
107		second: readonly DistEntry[],
108	): readonly string[] {
109		const right = new Map(second.map((entry) => [entry.path, entry.sha256]));
110		const differing: string[] = [];
111		for (const entry of first) {
112			const other = right.get(entry.path);
113			if (other === undefined || other !== entry.sha256) differing.push(entry.path);
114		}
115		for (const entry of second) if (!first.some((left) => left.path === entry.path)) differing.push(entry.path);
116		return Object.freeze([...new Set(differing)].sort());
117	}
118	
119	/** The era baseline lane record, built from two consecutive rebuild inventories. */
120	export function buildEraLaneRecord(input: LaneInput): SealedRecord {
121		const stable = isByteStable(input.first, input.second);
122		const differing = differingPaths(input.first, input.second);
123		return sealRecord({
124			schemaVersion: 'versionless.angular-super-productivity-era-baseline.v1',
125			unit: UNIT,
126			consentId: CONSENT,
127			result: input.first.length > 0 && stable ? 'byte-stable' : 'rebuilt-green-not-byte-stable',
128			cell: {
129				node: input.nodeVersion,
130				architecture: 'darwin-x64 executed on darwin-arm64 through Rosetta 2',
131				packageManager: 'yarn 1.21.1',
132				command: 'node --max_old_space_size=4096 ./node_modules/@angular/cli/bin/ng build --aot --prod',
133				builder: '@angular-devkit/build-angular:browser 0.803.4 over webpack 4',
134				compiler: 'pre-Ivy ViewEngine, AOT — enableIvy appears in none of the 967 blobs and Angular 8.2 defaults to ViewEngine',
135				honestLabel:
136					"repository-declared as to major. .travis.yml pins `node_js: '12'`, which is what this cell runs; the patch level 12.14.1 and yarn 1.21.1 are the ingest's era-consistent choices, because the repository declares neither. The yarn 1.22.11-and-later defect recorded by the ingest — newer yarn walks up the directory tree, finds the host monorepo's packageManager field and demands Corepack — is avoided by the same fix the ingest recorded, not re-discovered.",
137			},
138			source: {
139				repository: 'super-productivity/super-productivity',
140				commit: '2943c5c4f13c3ce4dece0abf4f9c39739dde4192',
141				cache: '.versionless/cache/angular-super-productivity-v2-13-15-baseline',
142				provenance:
143					'Restored in this checkout from the u16 ingest: the era dependency closure installed by `yarn install --frozen-lockfile --ignore-scripts --non-interactive` against the committed 466,548-byte yarn.lock, 1061 top-level entries, lockfile unmutated.',
144				variant: ERA_VARIANT,
145				deviation: 'none. Nothing was pinned, patched or worked around in either rebuild, and no source file was modified.',
146			},
147			builds: [
148				{ run: 2, status: 0, files: input.first.length, seconds: input.firstSeconds },
149				{
150					run: 3,
151					status: 0,
152					files: input.second.length,
153					seconds: null,
154					secondsNote:
155						'Rebuilds 1 and 2 were timed by the harness that ran them (95 s and 90 s). Rebuild 3 was added afterwards to isolate the divergence and its wall clock was not captured; a duration is left null rather than estimated.',
156				},
157			],
158			rebuildComparison: REBUILD_COMPARISON,
159			byteStable: stable,
160			byteStableMeaning: stable
161				? 'The two rebuilds emit the same inventory, file for file and digest for digest, from the restored era closure.'
162				: 'The two rebuilds do not emit the same inventory. Both exited zero and emitted the same file count, and the paths below carry different bytes between them. This is a property of the fixture and its era toolchain that the ingest\'s single build could not have detected; it is recorded, not repaired, and no deviation was introduced to make it go away.',
163			differingPaths: differing,
164			instability: input.instability,
165			inventory: input.first,
166			recordedRisks: RECORDED_RISKS,
167			notEstablished: ERA_NOT_ESTABLISHED,
168		});
169	}
170	
171	/** Every `.ts` module below a directory, as workspace files. */
172	async function typescriptModulesBelow(directory: string, root: string): Promise<WorkspaceFile[]> {
173		const files: WorkspaceFile[] = [];
174		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
175			left.name < right.name ? -1 : 1,
176		)) {
177			const item = path.join(directory, entry.name);
178			if (entry.isDirectory()) {
179				files.push(...(await typescriptModulesBelow(item, root)));
180				continue;
181			}
182			if (!entry.isFile() || path.extname(entry.name) !== '.ts') continue;
183			files.push({ path: path.relative(root, item), source: await readFile(item, 'utf8') });
184		}
185		return files;
186	}
187	
188	/** Every stylesheet below a directory, as workspace files. */
189	async function styleSheetsBelow(directory: string, root: string): Promise<WorkspaceFile[]> {
190		const files: WorkspaceFile[] = [];
191		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
192			left.name < right.name ? -1 : 1,
193		)) {
194			const item = path.join(directory, entry.name);
195			if (entry.isDirectory()) {
196				files.push(...(await styleSheetsBelow(item, root)));
197				continue;
198			}
199			if (!entry.isFile() || path.extname(entry.name) !== '.scss') continue;
200			files.push({ path: path.relative(root, item), source: await readFile(item, 'utf8') });
201		}
202		return files;
203	}
204	
205	/** Every component template below a directory, as workspace files. */
206	async function templatesBelow(directory: string, root: string): Promise<WorkspaceFile[]> {
207		const files: WorkspaceFile[] = [];
208		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
209			left.name < right.name ? -1 : 1,
210		)) {
211			const item = path.join(directory, entry.name);
212			if (entry.isDirectory()) {
213				files.push(...(await templatesBelow(item, root)));
214				continue;
215			}
216			if (!entry.isFile() || path.extname(entry.name) !== '.html') continue;
217			files.push({ path: path.relative(root, item), source: await readFile(item, 'utf8') });
218		}
219		return files;
220	}
221	
222	/** Every workspace-relative path the tree carries, excluding installed packages. */
223	async function workspacePathsBelow(directory: string, root: string): Promise<string[]> {
224		const paths: string[] = [];
225		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
226			left.name < right.name ? -1 : 1,
227		)) {
228			if (entry.name === 'node_modules' || entry.name === '.git') continue;
229			const item = path.join(directory, entry.name);
230			if (entry.isDirectory()) {
231				paths.push(...(await workspacePathsBelow(item, root)));
232				continue;
233			}
234			if (entry.isFile()) paths.push(path.relative(root, item));
235		}
236		return paths;
237	}
238	
239	/**
240	 * Compute the composed changeset for the pinned tree.
241	 *
242	 * The workspace configuration handed in is a modern `angular.json`, so no
243	 * format lift is needed and the synthesis capability stands down on its own —
244	 * it reads the document's shape, and nothing here tells it which format to
245	 * expect.
246	 */
247	export async function composeMigration(tree: string): Promise<AngularMigration> {
248		const source = path.join(tree, 'src');
249		const sourceModules = (await typescriptModulesBelow(source, tree)).filter(
250			(module) => !module.path.endsWith('.spec.ts'),
251		);
252		return migrateAngularCliEraWorkspace(
253			{
254				packageManifest: {
255					path: 'package.json',
256					source: await readFile(path.join(tree, 'package.json'), 'utf8'),
257				},
258				workspaceConfig: {
259					path: 'angular.json',
260					source: await readFile(path.join(tree, 'angular.json'), 'utf8'),
261				},
262				tsConfig: {
263					path: 'tsconfig.json',
264					source: await readFile(path.join(tree, 'tsconfig.json'), 'utf8'),
265				},
266				sourceModules,
267				templates: await templatesBelow(source, tree),
268				styleSheets: await styleSheetsBelow(source, tree),
269				workspaceFiles: await workspacePathsBelow(tree, tree),
270			},
271			ANGULAR_16_BROWSER_CELL,
272		);
273	}
274	
275	/**
276	 * Era facts of this fixture that the workspace migration has to carry across
277	 * the hop or declare it dropped. They are recorded by name because a changeset
278	 * that silently loses one of them would still look clean.
279	 */
280	export const ERA_WORKSPACE_FACTS: readonly string[] = Object.freeze([
281		'ngsw-config.json plus the production `serviceWorker: true` option: the era build emits ngsw-worker.js, safety-worker.js and a generated ngsw.json, and the config file declares an external asset group that prefetches Google Fonts at runtime.',
282		'tsconfig.worker.json wired through the browser builder\'s `webWorkerTsConfig` option: two application web workers (lz, reminder) compile and emit as their own chunks in the era build.',
283		'`extractCss: true` on the production configuration — a valid key for the Angular 8 browser builder, and one the Angular 13 line removed.',
284		'A second workspace project, sp2-e2e, whose only targets are the protractor e2e runner and a TSLint lint target.',
285		'`cli.defaultCollection: "@ngrx/schematics"`, which names a schematics collection rather than a build input.',
286		'A `jo` devDependency declared as `file:./tools/schematics` — a workspace-local schematics package built by the repository\'s own `buildSchema` script.',
287	]);
288	
289	/**
290	 * The changeset record. Every file is recorded by path and by digest before and
291	 * after; the sources themselves are not copied into evidence, because the tree
292	 * they came from is identified by commit sha and archive digest already.
293	 */
294	export function buildChangesetRecord(migration: AngularMigration): SealedRecord {
295		return sealRecord({
296			schemaVersion: 'versionless.angular-super-productivity-composed-changeset.v1',
297			unit: UNIT,
298			consentId: CONSENT,
299			cell: migration.cell,
300			appliedTo:
301				'The pinned revision as materialised at .versionless/cache/angular-super-productivity-v2-13-15-source/verify/extracted, whose blob-level reconciliation against the git tree — 967 blobs, zero mismatches — is recorded in the u16 ingest.',
302			spinePosition:
303				'The fourth independent application driven over the Angular adapter spine, and the first from the Angular 8 pre-Ivy ViewEngine era. No capability was written for this application; the changeset is what the existing inventory produced when it was pointed at a tree it had never seen.',
304			eraWorkspaceFacts: ERA_WORKSPACE_FACTS,
305			applicationFilesScanned: migration.applicationFilesScanned,
306			applicationFilesChanged: migration.applicationFilesChanged,
307			workspaceFilesChanged: migration.workspaceFilesChanged,
308			files: migration.files.map((entry) => ({
309				path: entry.path,
310				kind: entry.kind,
311				changed: entry.changed,
312				sha256Before: entry.sha256Before,
313				sha256After: entry.sha256After,
314				changes: entry.changes,
315			})),
316			removedFiles: migration.removedFiles,
317			declaredDifferences: migration.declaredDifferences,
318			unhandled: migration.unhandled,
319			notEstablished: [
320				'A composed changeset is a set of edits, not a build. Nothing here establishes that the migrated tree installs, compiles or emits anything; no install was performed and no build was attempted by this unit.',
321				'`applicationFilesChanged` counts application source the transforms rewrote. A file the adapter scanned and left alone is counted as scanned and not as changed.',
322				'A cell disposition is a reading of a registry, not an installation. A range written here has not been resolved against a lockfile by this unit.',
323			],
324		});
325	}
326	
327	export async function main(): Promise<void> {
328		const nodeVersion = (await readFile(path.join(BASELINE_DIRECTORY, 'rebuild-node.txt'), 'utf8')).trim();
329		const first = await inventoryOf(path.join(BASELINE_DIRECTORY, 'dist-run2'));
330		const second = await inventoryOf(path.join(BASELINE_DIRECTORY, 'dist-run3'));
331		const seconds = async (file: string): Promise<number> =>
332			Number.parseInt((await readFile(path.join(BASELINE_DIRECTORY, file), 'utf8')).trim(), 10);
333		const era = verifySealedRecord(
334			buildEraLaneRecord({
335				first,
336				second,
337				firstSeconds: await seconds('rebuild-2.seconds'),
338				nodeVersion,
339				instability: INSTABILITY,
340			}),
341		);
342		const migration = await composeMigration(SOURCE_TREE);
343		const changeset = verifySealedRecord(buildChangesetRecord(migration));
344		await mkdir(EVIDENCE_DIRECTORY, { recursive: true });
345		await writeFile(path.join(EVIDENCE_DIRECTORY, ERA_LANE_FILE), canonical(era));
346		await writeFile(path.join(EVIDENCE_DIRECTORY, CHANGESET_FILE), canonical(changeset));
347		process.stdout.write(
348			`era lane ${String(era['result'])} over ${String(first.length)} files; changeset: ` +
349				`${String(migration.applicationFilesChanged)}/${String(
350					migration.applicationFilesScanned,
351				)} application files changed, ${String(migration.workspaceFilesChanged)} workspace, ` +
352				`${String(migration.unhandled.length)} unhandled, ${String(
353					migration.declaredDifferences.length,
354				)} declared differences, changeset digest ${sha256(canonical(changeset)).slice(0, 12)}\n`,
355		);
356	}
357	
358	/**
359	 * What was found when each differing path was chased, as measured by a third
360	 * consecutive build of the same tree.
361	 */
362	export const INSTABILITY: readonly InstabilityFinding[] = Object.freeze([
363		Object.freeze({
364			path: './ngsw.json',
365			observed:
366				'The generated service-worker manifest differs between every pair of builds.',
367			cause:
368				'ngsw.json carries a `timestamp` field that the service-worker builder fills with the wall clock at generation time, and a `hashTable` keyed by the emitted filenames — so it moves both on its own and whenever a hashed filename moves.',
369			consequential: false,
370		}),
371		Object.freeze({
372			path: './index.html',
373			observed:
374				'The emitted entry document differs between builds that emit differing main chunks.',
375			cause:
376				'index.html carries the content-hashed filename of the main chunk in its script tag. It is downstream of the main chunk and moves only because that moved.',
377			consequential: false,
378		}),
379		Object.freeze({
380			path: 'main.<contenthash>.js and its .map',
381			observed:
382				'The application chunk carries a different content hash and different bytes on every build, so no two builds even agree on the filename. Three consecutive rebuilds produced three distinct main chunks of three different byte lengths.',
383			cause:
384				'Chased to a single line rather than inferred. The first differing byte between two consecutive main chunks falls inside an inlined component stylesheet, in a `@keyframes bang` rule whose box-shadow list is generated by Sass `random()` — src/app/pages/daily-summary/daily-summary.component.scss line 184, `random($width)-$width / 2 + px random($height)-$height / 1.2 + px hsl(random(360), 100, 50)`. Sass `random()` is unseeded, so node-sass emits different literals on every compile, the component stylesheet is inlined into the application chunk, and the chunk\'s content hash moves with it. The workspace-level styles.css is byte-identical across all three builds, which is consistent: the confetti rule lives in a component stylesheet, not the global one.',
385			consequential: true,
386		}),
387	]);
388	
389	/**
390	 * What the three consecutive rebuilds establish together, stated once so the
391	 * lane record does not have to be read as three separate comparisons.
392	 */
393	export const REBUILD_COMPARISON =
394		'Three consecutive rebuilds of the unmodified pinned tree were run on the same host in the same session. All three exited zero and all three emitted the same 64-file inventory. No two of them agree: rebuild 1 emitted main.6871f8597c3fbcf77df6.js, rebuild 2 main.2b292dc79b76876e9ea9.js and rebuild 3 main.932307a6bf1518696bcc.js, each with its own map, its own index.html script tag and its own ngsw.json hash table. The comparison pair recorded in `inventory` and `differingPaths` is rebuilds 2 and 3, whose full dist trees are both retained; rebuild 1 is cited from its retained digest manifest. Adding a third build was not a repair attempt — it was how the cause was isolated, by giving the divergence a second independent sample instead of one.';
395	
396	if (process.argv[1]?.endsWith('angular-super-productivity-lanes-run.ts'))
397		main().catch((error: unknown) => {
398			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
399			process.exitCode = 1;
400		});
