/**
 * The rebuild half of the super-productivity migrated lane's binding-reorder
 * repair.
 *
 * u20c2b root-caused a per-load runtime regression in the migrated lane: Ivy
 * fires `@Input()` setters in template-binding order, where Angular 8 View
 * Engine applied them in directive-declaration order, so the `set splitPos`
 * accessor ran against a `this.splitTopEl` the sibling `[splitTopEl]` binding
 * had not populated yet and dereferenced `undefined.classList`. u20c2c landed
 * the generic `template-binding-reorder` capability in `@versionless/angular`
 * and wired it into the composed changeset; it fires exactly once, on the
 * `<split>` call site in `work-view-page.component.html`, moving `[splitTopEl]`
 * and `[splitBottomEl]` ahead of `[splitPos]` with the binding VALUES
 * untouched. This driver applies that composed changeset to the stage tree and
 * rebuilds the lane so the reorder reaches the built bytes.
 *
 * The build is the u23 methodology, reused rather than re-implemented: the same
 * `guardedBuild` — every build preloaded with u22's in-process egress guard,
 * which records and refuses any connection to a non-loopback address — and the
 * same `applyFontInliningDisable`, because re-applying the composed changeset
 * rewrites `angular.json` and would otherwise restore the font inliner u23
 * turned off. No control build is run here: u23 already measured the font-host
 * fetch, and this round's discriminator is the page-error count, measured in
 * the behavior driver beside this one, not the font seam. The two builds after
 * the capability are expected to make no egress attempt at all.
 *
 * Nothing about the split component, the reorder or this application is decided
 * here. Every decision about what to change lives in `@versionless/angular`;
 * this driver applies the changeset it composes and reads the result.
 */

import { writeFile } from 'node:fs/promises';
import * as path from 'pathe';
import { APPLIED_TREE, STAGE_DIRECTORY } from './angular-super-productivity-apply-run.ts';
import { composeMigration, SOURCE_TREE } from './angular-super-productivity-lanes-run.ts';
import { applyMigration } from './angular-tiny-translator-apply-run.ts';
import {
	applyFontInliningDisable,
	type BuildReading,
	type WorkspaceApplication,
} from './angular-tiny-translator-u22-font-run.ts';
import { guardedBuild } from './angular-super-productivity-u23-font-run.ts';

export const UNIT = 'lrapr-t006/u20c2d-rebuild-behavior-check';
/** The output roots this round emits; u23's dist-23/dist-24 are left untouched. */
export const CANONICAL_ROOT = 'dist-25';
export const REPEATED_ROOT = 'dist-26';

/** One application file the composed changeset rewrote, by path, kind and digests. */
export type AppliedFileFact = Readonly<{
	path: string;
	kind: string;
	changed: boolean;
	sha256Before: string | null;
	sha256After: string | null;
	changes: readonly string[];
}>;

export type RebuildRound = Readonly<{
	applicationFilesScanned: number;
	applicationFilesChanged: number;
	workspaceFilesChanged: number;
	/** Every changed application file, by path and kind, so the reorder can be located among them. */
	changedApplicationFiles: readonly Readonly<{ path: string; kind: string }>[];
	/** The `<split>` call-site template the reorder rewrote, or null if it did not fire. */
	reorderedTemplate: AppliedFileFact | null;
	fontApplication: WorkspaceApplication;
	builds: readonly BuildReading[];
}>;

const CALL_SITE_TEMPLATE = 'src/app/pages/work-view/work-view-page.component.html';

/**
 * Apply the composed changeset — now carrying the binding reorder — into the
 * stage tree, restore the font-inlining-disable the re-application would undo,
 * and build twice under the egress guard.
 */
export async function runRebuildRound(): Promise<RebuildRound> {
	const migration = await composeMigration(SOURCE_TREE);
	await applyMigration(migration, APPLIED_TREE);
	const fontApplication = await applyFontInliningDisable(APPLIED_TREE);
	const first = await guardedBuild('build-25', CANONICAL_ROOT);
	const second = await guardedBuild('build-26', REPEATED_ROOT);
	const reordered = migration.files.find((entry) => entry.path === CALL_SITE_TEMPLATE);
	return Object.freeze({
		applicationFilesScanned: migration.applicationFilesScanned,
		applicationFilesChanged: migration.applicationFilesChanged,
		workspaceFilesChanged: migration.workspaceFilesChanged,
		changedApplicationFiles: Object.freeze(
			migration.files
				.filter((entry) => entry.changed && entry.kind !== 'workspace')
				.map((entry) => Object.freeze({ path: entry.path, kind: entry.kind })),
		),
		reorderedTemplate:
			reordered === undefined
				? null
				: Object.freeze({
						path: reordered.path,
						kind: reordered.kind,
						changed: reordered.changed,
						sha256Before: reordered.sha256Before,
						sha256After: reordered.sha256After,
						changes: Object.freeze([...reordered.changes]),
					}),
		fontApplication,
		builds: Object.freeze([first, second]),
	});
}

export async function main(): Promise<void> {
	const round = await runRebuildRound();
	await writeFile(
		path.join(STAGE_DIRECTORY, 'u20c2d-round.json'),
		`${JSON.stringify(round, null, '\t')}\n`,
	);
	process.stdout.write(
		`applied ${String(round.applicationFilesChanged)} application file(s); ` +
			`reorder fired: ${String(round.reorderedTemplate !== null)}\n`,
	);
	for (const site of round.fontApplication.sites) process.stdout.write(`font-disable: ${site.at}\n`);
	for (const build of round.builds)
		process.stdout.write(
			`${build.name} exit ${String(build.exitStatus)}, ` +
				`${String(build.egressAttempts.length)} egress attempt(s)\n`,
		);
}

if (process.argv[1]?.endsWith('angular-super-productivity-u20c2d-run.ts'))
	main().catch((error: unknown) => {
		process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
		process.exitCode = 1;
	});

